  */
#define __LL_RCC_CALC_PLL1CLK_SAI_FREQ(__INPUTFREQ__, __PLL1M__, __PLL1N__, __PLL1P__) ((((__INPUTFREQ__) \
    /(__PLL1M__)) * (__PLL1N__)) / (__PLL1P__))
